begin;
select plan(8);
select ok(not has_table_privilege('anon','public.books_native_invoice_correction_proposals','select,insert') and not has_table_privilege('authenticated','public.books_native_invoice_correction_proposals','select,insert'),'native correction proposals are private');
select ok(has_table_privilege('service_role','public.books_native_invoice_correction_proposals','select,insert') and not has_table_privilege('service_role','public.books_native_invoice_correction_proposals','update,delete'),'server may append but cannot rewrite correction proposals');
select ok((select relrowsecurity from pg_class where oid='public.books_native_invoice_correction_proposals'::regclass),'native correction proposals have RLS enabled');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_native_invoice_correction_proposals'::regclass and tgname='books_native_invoice_correction_proposal_immutable'),'native correction proposals are immutable');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_native_invoice_correction_proposals'::regclass and tgname='books_native_invoice_correction_proposal_guard'),'direct insertion derives original journal evidence');
select ok(not has_function_privilege('anon','public.prepare_books_native_invoice_correction(uuid,uuid,uuid,uuid,jsonb)','execute') and not has_function_privilege('authenticated','public.prepare_books_native_invoice_correction(uuid,uuid,uuid,uuid,jsonb)','execute'),'public clients cannot bypass correction authorization');
select ok(has_function_privilege('service_role','public.prepare_books_native_invoice_correction(uuid,uuid,uuid,uuid,jsonb)','execute') and not (select prosecdef from pg_proc where oid='public.prepare_books_native_invoice_correction(uuid,uuid,uuid,uuid,jsonb)'::regprocedure),'native correction preparation retains INVOKER authority');
select ok((select count(*)=2 from pg_constraint where conrelid='public.books_native_invoice_correction_proposals'::regclass and contype='f' and confrelid in('public.books_native_invoice_postings'::regclass,'public.books_native_journal_entries'::regclass) and cardinality(conkey)=3),'native correction originals have organization and entity scoped references');
select * from finish();
rollback;
